function buildRowsFromRequiredDays(
  logsByDate: Map<string, WeeklyReportLogEntry>,
  requiredDays: WeeklyReportRequiredDay[],
) {
  return [...requiredDays]
    .sort((left, right) => left.date.localeCompare(right.date))
    .flatMap((requiredDay) => {
      if (requiredDay.status !== "complete") {
        return [];
      }

      const log = logsByDate.get(requiredDay.date);

      if (!log) {
        return [];
      }

      return [
        {
          activity: log.activity,
          activityRichText: log.activityRichText ?? null,
          checkIn: formatOfficialTime(log.checkIn),
          checkOut: formatOfficialTime(log.checkOut),
          date: formatOfficialDate(log.date),
          isBlank: false,
        } satisfies PolinemaLogbookRow,
      ];
    });
}

