export function buildPolinemaPrintableRows(report: WeeklyReportDocument): PolinemaLogbookRow[] {
  const logsByDate = new Map(report.logs.map((log) => [log.date, log]));
  const filledRows = buildRowsFromRequiredDays(logsByDate, report.requiredDays);
  const blankRowCount = Math.max(0, POLINEMA_PRINTABLE_BODY_ROWS - filledRows.length);

  return [
    ...filledRows,
    ...Array.from({ length: blankRowCount }, () => ({
      activity: "",
      activityRichText: null,
      checkIn: "",
      checkOut: "",
      date: "",
      isBlank: true,
    } satisfies PolinemaLogbookRow)),
  ].slice(0, POLINEMA_PRINTABLE_BODY_ROWS);
}

