const routeRoleMap: Record<string, AuthRole[]> = {
  "/manual-control": ["OPERATOR", "SUPERVISOR", "ADMINISTRATOR"],
  "/settings": ["SUPERVISOR", "ADMINISTRATOR"],
  "/users-roles": ["ADMINISTRATOR"],
  "/audit-log": ["SUPERVISOR", "ADMINISTRATOR"],
};

export function canAccessRoute(pathname: string, role: AuthRole) {
  const match = Object.entries(routeRoleMap).find(([route]) => pathname.startsWith(route));
  if (!match) {
    return true;
  }

  return match[1].includes(role);
}

