def _find_rule_candidates(field: dict, rules: dict) -> list[tuple[str, dict, float, str]]:
    label = str(field.get("label", ""))
    normalized = _normalize_text(label)
    tokens = _token_set(label)
    field_id = str(field.get("id", "")).strip()

    if not rules:
        return []

    norm_map = {_normalize_text(str(key)): str(key) for key in rules.keys()}
    by_id_map = {_entry_from_rule_key(str(key)): str(key) for key in rules.keys() if _entry_from_rule_key(str(key))}

    candidates: list[tuple[str, dict, float, str]] = []

    if field_id and field_id in by_id_map:
        key = by_id_map[field_id]
        candidates.append((key, rules[key], 1.0, "entry_id_exact"))

    if label in rules:
        candidates.append((label, rules[label], 0.99, "label_exact"))

    if normalized in norm_map:
        key = norm_map[normalized]
        candidates.append((key, rules[key], 0.98, "label_normalized"))

    for alias_values in ALIAS_HINTS.values():
        if tokens.intersection(alias_values):
            for key, value in rules.items():
                key_tokens = _token_set(str(key))
                if key_tokens.intersection(alias_values):
                    candidates.append((str(key), value, 0.96, "alias"))

    # Token-overlap matching for long labels/questions.
    for key, value in rules.items():
        key_tokens = _token_set(str(key))
        if not key_tokens:
            continue
        inter = tokens.intersection(key_tokens)
        if not inter:
            continue
        union = tokens.union(key_tokens)
        overlap = len(inter) / max(1, len(union))
        keyword_boost = 0.08 if inter.intersection(SEMANTIC_KEYWORDS) else 0.0
        score = overlap + keyword_boost
        if score >= 0.34:
            candidates.append((str(key), value, min(0.95, score), "token_overlap"))

    best_key = ""
    best_ratio = 0.0
    for key in rules.keys():
        ratio = SequenceMatcher(a=normalized, b=_normalize_text(str(key))).ratio()
        if ratio > best_ratio:
            best_ratio = ratio
            best_key = str(key)
    if best_ratio >= 0.9 and best_key:
        candidates.append((best_key, rules[best_key], best_ratio, "fuzzy"))

    uniq: dict[tuple[str, str], tuple[str, dict, float, str]] = {}
    for key, rule, score, mode in candidates:
        idx = (key, mode)
        if idx not in uniq or uniq[idx][2] < score:
            uniq[idx] = (key, rule, score, mode)

    return sorted(uniq.values(), key=lambda item: item[2], reverse=True)

def _trace_from_fill_plan(fill_plan: list[dict], payload: dict[str, str]) -> list[dict]:
    trace: list[dict] = []
    for plan in fill_plan:
        field_id = str(plan.get("id", "")).strip()
        if not field_id or field_id not in payload:
            continue
        source = str(plan.get("value_source", "ai")).lower()
        if source == "python_rule":
            resolved_by = "rule"
            confidence = "high"
        elif source == "gemini_rule":
            resolved_by = "rule"
            confidence = "medium"
        elif source in {"python_fallback", "fallback"}:
            resolved_by = "fallback"
            confidence = "low"
        else:
            resolved_by = "ai"
            confidence = "medium"
        trace.append(
            {
                "id": field_id,
                "label": str(plan.get("label", field_id)),
                "resolved_by": resolved_by,
                "confidence": confidence,
                "success": True,
                "reason": "generated",
            }
        )
    return trace

export function deriveCheckStatus(args: {
  checkData: RunPreviewResponse | null;
  checkIsStale: boolean;
  isChecking: boolean;
  runCompleted: boolean;
}): CheckReadinessStatus {
  if (args.isChecking) return "running";
  if (args.runCompleted) return "completed";
  if (!args.checkData) return "not_checked";
  if (args.checkIsStale) return "not_checked";
  if ((args.checkData.summary.blocked_count ?? 0) > 0) return "blocked";
  if ((args.checkData.summary.ready_with_warnings_count ?? 0) > 0) return "ready_with_warnings";
  return "ready";
}

export function resolveCheckGateMessage(args: {
  hasAnalyzed: boolean;
  respondentCount: number;
  baseRunDisabledReason: string | null;
  checkData: RunPreviewResponse | null;
  checkIsStale: boolean;
  lang?: UiLang;
}): string | null {
  const lang = args.lang ?? "id";
  if (args.baseRunDisabledReason) return args.baseRunDisabledReason;
  if (!args.hasAnalyzed || args.respondentCount < 1) return null;
  if (!args.checkData) {
    return lang === "en" ? "Run Quick Check first." : "Jalankan Cek Kesiapan terlebih dahulu.";
  }
  if (args.checkIsStale) {
    return lang === "en"
      ? "Quick Check result is stale. Run Quick Check again."
      : "Hasil Cek Kesiapan sudah berubah. Jalankan ulang Cek Kesiapan.";
  }
  if ((args.checkData.summary.blocked_count ?? 0) > 0) {
    return lang === "en"
      ? `${args.checkData.summary.blocked_count} blockers found. Fix them before running automation.`
      : `Terdapat ${args.checkData.summary.blocked_count} penghambat. Perbaiki sebelum menjalankan otomasi.`;
  }
  return null;
}

