function clamp(value: number, min = 0, max = 100) {
 return Math.min(max, Math.max(min, value));
}

function categoryFor(mastery: number): StudyRecommendation["category"] {
 if (mastery < 40) return "Remedial";
 if (mastery < 70) return "Latihan";
 if (mastery < 85) return "Penguatan";
 return "Lanjut";
}

function reasonFor(evidence: CompetencyEvidence) {
 const incorrect = Math.max(0, evidence.recentTotal - evidence.recentCorrect);
 if (evidence.mastery < 40) {
 return `${incorrect} dari ${evidence.recentTotal} respons terakhir belum tepat dan penguasaan ${evidence.competency} masih ${evidence.mastery}%.`;
 }
 if (evidence.mastery < 70) {
 return `Penguasaan ${evidence.competency} sudah ${evidence.mastery}%, tetapi masih perlu latihan terarah agar lebih konsisten.`;
 }
 if (evidence.mastery < 85) {
 return `Penguasaan ${evidence.competency} mencapai ${evidence.mastery}%. Materi penguatan membantu menjaga konsistensi sebelum naik tingkat.`;
 }

