export async function createSession(userId: string, context?: { ipAddress?: string | null; userAgent?: string | null }) {
 const rawToken = createOpaqueToken();
 const expiresAt = new Date(Date.now() + SESSION_HOURS * 60 * 60 * 1000);
 await db.insert(sessions).values({
 userId,
 tokenHash: hashToken(rawToken),
 expiresAt,
 ipAddress: context?.ipAddress ?? null,
 userAgent: context?.userAgent ?? null,
 });
 return { rawToken, expiresAt };
}

export function attachSessionCookie(response: NextResponse, rawToken: string, expiresAt: Date) {
 response.cookies.set(SESSION_COOKIE, rawToken, {
 httpOnly: true,
 sameSite: "lax",
 secure: process.env.NODE_ENV === "production",
 path: "/",
 expires: expiresAt,
 priority: "high",
 });
}
